$res=$conn->query("SELECT p.id,p.name,p.price,p.image,p.stock,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.tab_name='recent' AND p.is_active=1 ORDER BY p.created_at DESC");while($res&&$r=$res->fetch_assoc())$recent[]=$r;
